"""Base class every vendor plugin extends."""
from __future__ import annotations

from ..model import Device, Network, Trunk, Vlan


class Vendor:
    #: registry key used in the network file, e.g. "cisco_ios"
    key: str = ""
    #: human readable name
    title: str = ""
    #: device families this plugin covers (shown in `vlantool vendors`)
    covers: str = ""
    #: Netmiko device_type for SSH push, or None if push is not possible
    netmiko_type: str | None = None
    #: True if config is a list of CLI commands that can be pushed line by line
    pushable: bool = True
    #: let Netmiko enter config mode before sending (off for CLIs that mix modes)
    push_enter_config: bool = True
    #: Junos/EdgeOS style candidate config that needs an explicit commit
    commit: bool = False
    supports_switching: bool = True
    supports_policies: bool = False
    #: routed VLANs must hang off a physical parent interface (routers/firewalls)
    requires_parent: bool = False
    #: comment prefix for the header
    comment: str = "!"
    #: lines wrapped around the body when generating paste-able config
    #: (Netmiko enters/leaves config mode itself, so push skips them)
    config_enter: list[str] = []
    config_exit: list[str] = []

    def __init__(self, net: Network, device: Device):
        self.net = net
        self.dev = device

    # helpers ------------------------------------------------------------
    @property
    def vlans(self) -> list[Vlan]:
        return self.net.vlans_for(self.dev)

    @property
    def routed(self) -> list[Vlan]:
        return [self.net.vlans[i] for i in self.dev.routed_vlans]

    @property
    def trunks(self) -> list[Trunk]:
        return self.dev.trunks

    def vlan(self, vid: int) -> Vlan:
        return self.net.vlans[vid]

    def access_by_vlan(self) -> dict[int, list[str]]:
        out: dict[int, list[str]] = {}
        for port, vid in self.dev.access.items():
            out.setdefault(vid, []).append(port)
        return out

    def untagged_ports(self, vid: int) -> list[str]:
        """Access ports in vid plus trunks whose native VLAN is vid."""
        ports = [p for p, v in self.dev.access.items() if v == vid]
        ports += [t.port for t in self.trunks if t.native == vid]
        return ports

    def tagged_ports(self, vid: int) -> list[str]:
        return [t.port for t in self.trunks if vid in t.allowed and t.native != vid]

    def header(self) -> list[str]:
        c = self.comment
        return [
            f"{c} Generated by vlantool for {self.dev.name} ({self.title})",
            f"{c} VLANs: {', '.join(f'{v.id} {v.name}' for v in self.vlans) or 'none'}",
        ]

    # override -----------------------------------------------------------
    def render(self) -> list[str]:
        raise NotImplementedError

    def generate(self) -> str:
        return "\n".join(self.header() + self.config_enter + self.render()
                         + self.config_exit) + "\n"

    def push_commands(self) -> list[str]:
        """Commands sent over SSH: everything except comments and blanks."""
        return [line for line in self.render()
                if line.strip() and not line.lstrip().startswith(self.comment)]
